<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Island & Lighthouse</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #ui-container {
            position: absolute;
            bottom: 20px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            gap: 15px;
            background: rgba(0, 0, 0, 0.3);
            padding: 10px 20px;
            border-radius: 30px;
            backdrop-filter: blur(5px);
            border: 1px solid rgba(255, 255, 255, 0.2);
        }
        button {
            background: #fff;
            border: none;
            padding: 10px 20px;
            border-radius: 20px;
            cursor: pointer;
            font-weight: bold;
            color: #333;
            transition: all 0.3s ease;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-size: 0.8rem;
        }
        button:hover {
            transform: scale(1.05);
            background: #ff9a9e;
            color: white;
            box-shadow: 0 4px 10px rgba(0,0,0,0.2);
        }
        button#night-mode.active {
            background: #ff9a9e;
            color: white;
            box-shadow: 0 0 15px #ff9a9e;
        }
    </style>
</head>
<body>

<div id="ui-container">
    <button id="night-mode">Moon Mode</button>
</div>

<script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // Day sky
    scene.fog = new THREE.Fog(0x87CEEB, 20, 120);

    const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 25, 40);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.maxPolarAngle = Math.PI / 2 - 0.05; // Prevent going underwater

    // --- Lighting (Daytime) ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const sunLight = new THREE.DirectionalLight(0xffffff, 1.2);
    sunLight.position.set(50, 80, 50);
    sunLight.castShadow = true;
    sunLight.shadow.mapSize.width = 2048;
    sunLight.shadow.mapSize.height = 2048;
    sunLight.shadow.camera.near = 0.5;
    sunLight.shadow.camera.far = 200;
    // Increase shadow size for low-poly feel
    sunLight.shadow.bias = -0.0001;
    scene.add(sunLight);

    // --- Helper: Vertex Displacement (Low Poly Wave Logic) ---
    const getTerrainHeight = (x, z) => {
        // Simple pseudo-noise formula
        return Math.sin(x * 0.1) * Math.cos(z * 0.1) * 6 +
               Math.sin(x * 0.3 + z * 0.2) * 3;
    };

    // --- The Ocean ---
    const waterGeo = new THREE.PlaneGeometry(200, 200, 64, 64);
    waterGeo.rotateX(-Math.PI / 2);

    const waterMat = new THREE.MeshStandardMaterial({
        color: 0x006994,
        flatShading: true,
        roughness: 0.2,
        metalness: 0.1,
        transparent: true,
        opacity: 0.9
    });
    const water = new THREE.Mesh(waterGeo, waterMat);
    water.position.y = -5;
    scene.add(water);

    // --- The Island Base ---
    const islandGeo = new THREE.PlaneGeometry(40, 40, 32, 32);
    islandGeo.rotateX(-Math.PI / 2);

    // Store vertices for wave animation later
    const islandPosAttribute = islandGeo.attributes.position;

    const islandBaseMat = new THREE.MeshStandardMaterial({
        color: 0x8B4513, // Dark dirt base
        flatShading: true
    });
    const islandBase = new THREE.Mesh(islandGeo, islandBaseMat);
    islandBase.receiveShadow = true;
    islandBase.position.y = -3;
    scene.add(islandBase);

    // --- Sand Terrain Generation ---
    const sandMat = new THREE.MeshStandardMaterial({
        color: 0xE6C288,
        flatShading: true
    });
    const sandGeo = new THREE.PlaneGeometry(40, 40, 64, 64);
    sandGeo.rotateX(-Math.PI / 2);

    // We will displace vertices immediately
    const sandMesh = new THREE.Mesh(sandGeo, sandMat);
    sandMesh.receiveShadow = true;
    sandMesh.castShadow = true;

    const sandPositions = sandGeo.attributes.position;
    const count = sandPositions.count;

    for (let i = 0; i < count; i++) {
        const x = sandPositions.getX(i);
        const y = sandPositions.getY(i);
        const z = sandPositions.getZ(i); // z is actually y in plane space

        // Create a raised island shape using noise-like functions
        let height = 0;

        // Central hump
        const dist = Math.sqrt(x*x + z*z);
        height += Math.max(0, (15 - dist) * 0.6);

        // Secondary peaks
        height += Math.sin(dist * 0.8) * Math.cos(x * 0.4) * 2;

        sandPositions.setZ(i, -4 + Math.max(0, height)); // -4 to sink below water
    }
    sandMesh.position.y = -3;
    scene.add(sandMesh);

    // --- The Lighthouse ---
    const lighthouseGroup = new THREE.Group();
    lighthouseGroup.position.set(12, 0, 12);

    // Base
    const baseGeo = new THREE.CylinderGeometry(1.5, 2, 4, 6);
    const baseMat = new THREE.MeshStandardMaterial({ color: 0xffffff, flatShading: true });
    const base = new THREE.Mesh(baseGeo, baseMat);
    base.position.y = 2;
    base.castShadow = true;
    base.receiveShadow = true;
    lighthouseGroup.add(base);

    // Window stripes
    const stripeGeo = new THREE.CylinderGeometry(1.6, 1.6, 3.95, 6, 1, true);
    const stripeMat = new THREE.MeshBasicMaterial({ color: 0x333333, side: THREE.DoubleSide });
    const stripes = new THREE.Mesh(stripeGeo, stripeMat);
    stripes.position.y = 2.5;
    lighthouseGroup.add(stripes);

    // Lantern Room
    const lanternGeo = new THREE.BoxGeometry(3, 3.5, 3);
    const lanternMat = new THREE.MeshStandardMaterial({ color: 0xffcc00, flatShading: true });
    const lantern = new THREE.Mesh(lanternGeo, lanternMat);
    lantern.position.y = 5.75;
    lantern.castShadow = true;
    lighthouseGroup.add(lantern);

    // Glass roof
    const roofGeo = new THREE.CylinderGeometry(1.6, 1.5, 0.5, 6);
    const roofMat = new THREE.MeshStandardMaterial({ color: 0x111111, metalness: 0.8, roughness: 0.1 });
    const roof = new THREE.Mesh(roofGeo, roofMat);
    roof.position.y = 7.5;
    lighthouseGroup.add(roof);

    scene.add(lighthouseGroup);

    // --- The Light Beam ---
    // The light is attached to the lantern to rotate with it, or parented separately.
    // We'll parent it to the lantern so it's always inside.
    const beamLight = new THREE.SpotLight(0xffaa00, 20);
    beamLight.position.set(0, 0, 0); // Relative to lantern
    beamLight.angle = Math.PI / 8;
    beamLight.penumbra = 0.3;
    beamLight.decay = 2;
    beamLight.distance = 100;
    beamLight.castShadow = true;
    beamLight.shadow.bias = -0.001;
    beamLight.target.position.set(0, 0, -50);
    lantern.add(beamLight);

    // The light beam visual (Cone)
    const beamGeo = new THREE.ConeGeometry(0.5, 40, 8);
    beamGeo.rotateX(Math.PI / 2);
    const beamMat = new THREE.MeshBasicMaterial({ 
        color: 0xffaa00, 
        transparent: true, 
        opacity: 0.15 
    });
    const beamMesh = new THREE.Mesh(beamGeo, beamMat);
    beamMesh.position.set(0, -1.5, 15);
    lantern.add(beamMesh);

    // --- The Palms ---
    function createPalm(x, z, scale, rotationY) {
        const palmGroup = new THREE.Group();
        palmGroup.position.set(x, 0, z);
        palmGroup.rotation.y = rotationY;

        // Trunk
        const trunkGeo = new THREE.CylinderGeometry(0.2, 0.4, 3, 5);
        const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8B4513, flatShading: true });
        const trunk = new THREE.Mesh(trunkGeo, trunkMat);
        trunk.position.y = 1.5;
        trunk.castShadow = true;
        palmGroup.add(trunk);

        // Leaves Cluster
        const leavesGroup = new THREE.Group();
        leavesGroup.position.y = 4;

        const leafGeo = new THREE.DodecahedronGeometry(0.6, 0);

        for(let i=0; i<5; i++) {
            const leaf = new THREE.Mesh(leafGeo, new THREE.MeshStandardMaterial({ color: 0x228B22, flatShading: true }));
            const angle = (i / 5) * Math.PI * 2;
            const offset = 1.2 + (i % 2) * 0.3;

            leaf.position.set(
                Math.cos(angle) * offset,
                Math.sin(angle) * offset,
                0
            );
            leaf.rotation.x = Math.PI / 2; // Face outward
            leavesGroup.add(leaf);
        }

        palmGroup.add(leavesGroup);

        // Tilt slightly for wind effect
        palmGroup.rotation.z = 0.1;
        scene.add(palmGroup);
    }

    createPalm(-8, 5, 1, 0.5);
    createPalm(5, 2, 1.2, -0.7);
    createPalm(-2, -8, 1.1, 1.3);

    // --- Animation Loop ---
    const clock = new THREE.Clock();
    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    function animate() {
        requestAnimationFrame(animate);

        const delta = clock.getDelta();
        const time = clock.getElapsedTime();

        // 1. Animate Water Waves
        if (islandBase) {
            const positions = islandPosAttribute.array;
            for (let i = 0; i < positions.length; i += 3) {
                const x = positions[i];
                const z = positions[i + 2];
                // Combine two sine waves for more organic movement
                positions[i + 1] = 
                    -Math.sin(x * 0.5 + time * 2) * 
                    Math.cos(z * 0.5 + time * 1.5) * 
                    (Math.random() > 0.5 ? 1 : -1) * 0.15;
            }
            islandBase.geometry.attributes.position.needsUpdate = true;
        }

        if (sandMesh) {
            const sPos = sandPositions.array;
            for (let i = 0; i < sPos.length; i += 3) {
                const x = sPos[i];
                const z = sPos[i + 2];
                // Slower waves for sand
                sPos[i + 1] = -Math.sin(x * 0.4 + time * 1) * 
                              Math.cos(z * 0.3 + time * 0.8) * 0.08;
            }
            sandMesh.geometry.attributes.position.needsUpdate = true;
        }

        // 2. Animate Lighthouse
        lantern.rotation.y += 0.01;
        // Subtle breathing of light
        const lightIntensity = 20 * (0.9 + Math.sin(time * 3) * 0.1);
        beamLight.intensity = lightIntensity;
        beamMesh.material.opacity = 0.1 + (lightIntensity / 30);

        // 3. Interactive Water Ripple on Mouse Move
        // Simple distance check for effect (optional polish)
        controls.update();
        renderer.render(scene, camera);
    }

    // --- Day/Night Toggle Logic ---
    const nightBtn = document.getElementById('night-mode');
    let isNight = false;

    nightBtn.addEventListener('click', () => {
        isNight = !isNight;

        if (isNight) {
            nightBtn.textContent = "Sun Mode";
            nightBtn.classList.add('active');

            // Fade scene to dark
            scene.background = new THREE.Color(0x050515);
            scene.fog.color.set(0x050515);

            // Move Sun down and dim
            sunLight.position.set(-20, 10, 30);
            sunLight.intensity = 0.4;
            sunLight.color.setHex(0xffddaa); // Warm moonlight

            // Turn on moon light (Ambient)
            ambientLight.intensity = 0.4;

        } else {
            nightBtn.textContent = "Moon Mode";
            nightBtn.classList.remove('active');

            // Restore day colors
            scene.background = new THREE.Color(0x87CEEB);
            scene.fog.color.set(0x87CEEB);

            // Restore Sun
            sunLight.position.set(50, 80, 50);
            sunLight.intensity = 1.2;
            sunLight.color.setHex(0xffffff);

            // Dim ambient
            ambientLight.intensity = 0.6;
        }
    });

    // --- Resize Handler ---
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    animate();

</script>
</body>
</html>
